from ortools.linear_solver import pywraplp
import json

def main():
    solver = pywraplp.Solver.CreateSolver("SCIP")
    INF = solver.infinity()

    warehouses = ['A', 'B']
    stores = [1, 2, 3, 4, 5]

    capacity = {'A': 100, 'B': 150}

    setup_cost = {'A': 5000, 'B': 7000}

    demand = {1: 50, 2: 70, 3: 40, 4: 60, 5: 30}

    trans_cost = {
        ('A', 1): 10, ('B', 1): 15,
        ('A', 2): 12, ('B', 2): 8,
        ('A', 3): 20, ('B', 3): 18,
        ('A', 4): 14, ('B', 4): 11,
        ('A', 5): 18, ('B', 5): 16
    }

    open_var = {}
    for i in warehouses:
        open_var[i] = solver.BoolVar(f"open_{i}")

    ship_var = {}
    for i in warehouses:
        for j in stores:
            ship_var[(i, j)] = solver.NumVar(0, INF, f"ship_{i}_{j}")

    for j in stores:
        constraint = sum(ship_var[(i, j)] for i in warehouses) == demand[j]
        solver.Add(constraint)

    for i in warehouses:
        constraint = sum(ship_var[(i, j)] for j in stores) <= capacity[i]
        solver.Add(constraint)

    for i in warehouses:
        constraint = sum(ship_var[(i, j)] for j in stores) <= capacity[i] * open_var[i]
        solver.Add(constraint)

    setup_cost_expr = sum(setup_cost[i] * open_var[i] for i in warehouses)
    trans_cost_expr = sum(trans_cost[(i, j)] * ship_var[(i, j)] for i in warehouses for j in stores)

    solver.Minimize(setup_cost_expr + trans_cost_expr)

    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL:
        total_cost = int(solver.Objective().Value())

        distribution_center_open = []
        for i in warehouses:
            distribution_center_open.append(1 if open_var[i].solution_value() > 0.5 else 0)

        order_allocations = []
        for j in stores:
            store_alloc = []
            for i in warehouses:
                value = ship_var[(i, j)].solution_value()
                store_alloc.append(int(round(value)))
            order_allocations.append(store_alloc)

        print(json.dumps({
            "total_cost": total_cost,
            "distribution_center_open": distribution_center_open,
            "order_allocations": order_allocations
        }))

    else:
        print(f"Solver status: {status}")
        if status == pywraplp.Solver.INFEASIBLE:
            print("Problem is infeasible")
        elif status == pywraplp.Solver.UNBOUNDED:
            print("Problem is unbounded")

if __name__ == "__main__":
    main()
